auth.probe_js:
// Do NOT gate on cookies here: the cookies that carry a Quora session are HttpOnly, and the ones
// document.cookie can see are set for signed-out visitors too. Ask the page's own state instead.
let why;
try {
  const g = window.ansFrontendGlobals;
  const u = g && ((g.data && g.data.viewer) || g.viewer || g.user);
  if (u && typeof u === 'object' && (u.id || u.uid || u.name || u.username)) {
    return {signed_in: true, as: u.name || u.username || undefined, why: 'ansFrontendGlobals names a viewer'};
  }
  if (g) why = 'ansFrontendGlobals present but names no viewer';
} catch (e) { why = 'ansFrontendGlobals read failed: ' + e.message; }
try {
  const scripts = document.querySelectorAll('script');
  for (let i = 0; i < scripts.length; i++) {
    const t = scripts[i].textContent || '';
    if (!t || t.length > 2000000) continue;
    const m = t.match(/"(?:is_logged_in|logged_in|isLoggedIn)"\s*:\s*(true|false)/);
    if (m) {
      if (m[1] === 'true') return {signed_in: true, why: 'inline bootstrap logged-in flag is true'};
      why = 'inline bootstrap logged-in flag is false';
      break;
    }
  }
} catch (e) { /* inline scan is best-effort; never fatal */ }
// DOM, LAST and deliberately scoped to the shell: a signed-OUT question page is full of
// a[href^="/profile/"] links belonging to ANSWER AUTHORS. An unscoped selector calls that signed in.
const prof = document.querySelector('#root header a[href^="/profile/"], header a[href^="/profile/"], nav a[href^="/profile/"]');
if (prof) {
  const href = prof.getAttribute('href') || '';
  return {signed_in: true, as: href.replace(/^\/profile\//, '') || undefined, why: 'profile link in the top shell'};
}
const wall = document.querySelector('form[action*="login"], a[href*="/login"], input[name="email"]');
return {signed_in: false, why: why || (wall ? 'login wall rendered' : 'no viewer state and no profile link in the shell')};
